//! **The alignment artifact, as the producer actually writes it.**
//!
//! This module is the server's reading of ONE thing: the `dataset-alignment` artifact the
//! producer package emits (DEC-6 records which package that is, and its path — naming it
//! here would put a domain package's vocabulary in a core module). Everything here was
//! measured against an artifact that producer WROTE — regenerated by their own
//! `tools/emit_reference_alignment.py`, which invokes the producer as a subprocess — and not
//! from a docstring, a design paragraph, or a return value of one of their internal
//! functions.
//!
//! ## Why that sentence is in this file
//!
//! This side has now had **three** recipe shapes, two of them wrong, and each wrong one was
//! reached by a more careful process than the one before:
//!
//! 1. a single-source recipe (`source_artifact_id` + one row vector) — invented here when the
//!    producer did not exist yet. It cannot express an integration over two datasets, which
//!    is the whole point.
//! 2. an inline SEGMENT model, obtained by extracting the producer's `build_vectors()` and
//!    running it. That function returns an **in-memory intermediate the producer consumes
//!    before writing**; it is not the wire format. *Running their code is not consuming their
//!    output.*
//! 3. this one: parsed from the artifact the producer WRITES.
//!
//! Both wrong shapes passed every test on this side, because every fixture spoke this side's
//! private dialect on both ends — a self-agreeing oracle across a seam. The test that settles
//! it is `tests/workstore/alignment_seam_test.rs`, which reads a producer-emitted artifact.
//!
//! ## The shape, measured
//!
//! ```text
//! structure = { encoding: "zarr_v3", kind: "table", axis: "unified_entities", n,
//!               key: "unified_key", key_sequence_digest,
//!               columns: [ unified_key, unified_<secondary>… ],
//!               arrays:  [],                       // ← empty; see D5 below
//!               aux:     [ … 8 members, each with a `role` … ],   // D18 dropped the 2 row vectors
//!               extents: { segments, sources, unified_entities,
//!                          levels_<col>_<i>… } }   // D18 dropped `alignment_rows`
//! meta      = { …, sources: [ { dataset_id, key_sequence_digest, n_rows } … ] }
//! ```
//!
//! **Members are addressed BY ROLE, never by array position.** The `aux` array's order is the
//! producer's business; a consumer that indexes it positionally is reading whatever happens
//! to be there today and will silently read something else the day a member is added.
//!
//! **The per-source digests live in `meta.sources[]`** — not in `structure`, and not as one
//! digest. That is what makes ITEM-20's precheck per-SOURCE: a row verifies against *its own*
//! source's digest, reached through its segment. There is no single leaf to pin.
//!
//! ## ⚠ D5 — the registered datatype and the emitted artifact DISAGREE
//!
//! The registered `dataset-alignment` datatype declares an `arrays[]` containing a `segments`
//! columnar table; the producer emits `arrays: []` and carries the segment vectors as `aux`
//! members instead, and it emits five member classes the declaration does not mention. This
//! was confirmed independently from both sides and is **open, not resolved**. This module is
//! deliberately built against what the producer EMITS, and it is the first thing that breaks
//! whichever way D5 is settled — so it is flagged here rather than quietly accommodated.

use serde_json::Value;

use ziee_core::AppError;

/// **The error code every alignment-declaration refusal carries (audit finding 12).**
///
/// These were `AppError::internal_error` → **500**, and a 500 sends an operator to the server
/// logs. Every one of them is a statement about PRODUCER OUTPUT: an `aux` list that is
/// missing, a role that is absent or duplicated, a member whose length contradicts the extent
/// it is measured in, `meta.sources` missing, a source count that disagrees with the
/// declaration. Nothing has gone wrong with the server — an artifact's declaration is
/// inconsistent, and the fix is at the producer or on that row.
///
/// This is the buckets rule again, and this branch has now paid for it four times: two
/// conditions sharing one message when they recommend different actions
/// (`failed` vs `unresolvable`, a 500 vs `GATHER_DTYPE_UNSUPPORTED`, "no dataset input" vs
/// "its inputs no longer exist", and now "the server broke" vs "this artifact's declaration
/// does not hold together").
const ALIGNMENT_DECLARATION_INVALID: &str = "ALIGNMENT_DECLARATION_INVALID";

/// One `aux` member's declaration — the handle, not the bytes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AlignmentMemberRef {
    /// Member path inside the alignment's zarr store (e.g. `segment_start`).
    pub path: String,
    /// The producer's ROLE for this member. The only thing this side matches on.
    pub role: String,
    pub dtype: String,
    pub shape: Vec<usize>,
    /// The named extents this member's dimensions are measured in.
    pub extent: Vec<String>,
}

impl AlignmentMemberRef {
    /// The member's length along its first dimension, or a refusal naming it.
    pub fn len0(&self) -> Result<usize, AppError> {
        self.shape.first().copied().ok_or_else(|| {
            AppError::bad_request(
                ALIGNMENT_DECLARATION_INVALID,
                format!(
                    "alignment member {:?} (role {:?}) declares an empty shape, so its length is \
                 unknown — a length this side GUESSED would be the wrong number of the right \
                 kind, which is the failure class this whole path exists to prevent",
                    self.path, self.role
                ),
            )
        })
    }
}

/// One SOURCE dataset of the alignment, read from `meta.sources[]`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AlignmentSource {
    pub dataset_id: String,
    /// The key sequence this source had WHEN THE ALIGNMENT WAS COMPUTED.
    ///
    /// `None` means the producer recorded none — **"unknown", never "matches"** (INV-5).
    pub key_sequence_digest: Option<String>,
    pub n_rows: usize,
}

/// Roles, exactly as the producer stamps them. Matched as strings and never positionally.
///
/// **D18 (ITEM-11): the per-output-row `alignment_row_source` / `alignment_row_segment`
/// vectors were DROPPED.** Under masking they were inert — the masked read reconstructs
/// output positions from `segments + mask + rank` (Stage B's `MaskPlan`) and never consults
/// a stored row vector — and on the aligned path they are equally redundant: rows are laid
/// out in DECLARED order, so output row `i` resolves to its `(source, row)` from the segment
/// table alone (`resolve_row`, a range search over `segment_start`/`segment_end`, INV-4). The
/// per-source `key_sequence_digest` (INV-5), not a row vector, is what guards positional
/// addressing.
pub mod role {
    pub const SEGMENT_DATASET: &str = "alignment_segment_dataset";
    pub const SEGMENT_START: &str = "alignment_segment_start";
    pub const SEGMENT_END: &str = "alignment_segment_end";
    pub const SEGMENT_ORDER: &str = "alignment_segment_order";
    /// Renamed by its OWNER: the role was named after a domain axis until stage 1's slot
    /// rework, which renamed it to match the member it has always written (`entity_index`)
    /// and the rest of an already entity-shaped vocabulary. This side had independently
    /// renamed its own constant a round earlier, for the same reason — convergence, not a
    /// collision, and the two ends now agree on the word AND the literal.
    pub const ENTITY_INDEX: &str = "alignment_entity_index";
    pub const ENTITY_EVIDENCE: &str = "alignment_entity_evidence";
    /// **Repeated** — one per (secondary column × source). Collected, never singular.
    pub const LEVEL_LOOKUP: &str = "alignment_level_lookup";
}

/// Extent names the producer declares. A vector's length is read from HERE and cross-checked
/// against the member's own shape, so a member and its extent cannot disagree unnoticed.
pub mod extent {
    // D18 (ITEM-11): `alignment_rows` was DROPPED with the two per-row vectors it measured;
    // `n_rows` now comes from `sum(meta.sources[].n_rows)` (the row axis is a concatenation).
    pub const SEGMENTS: &str = "segments";
    pub const SOURCES: &str = "sources";
    pub const UNIFIED_ENTITIES: &str = "unified_entities";
}

/// A producer-emitted alignment, read as METADATA.
///
/// Everything here comes out of `structure` + `meta`, which are producer-DECLARED JSON the
/// server reads as control plane. **No artifact byte is opened to build this** — see
/// `AlignmentVectors` for where that boundary bites.
#[derive(Debug, Clone)]
pub struct AlignmentPlan {
    pub axis: String,
    /// The unified key column (`structure.key`).
    pub key_column: String,
    /// The unified axis's own key-sequence digest, if declared.
    pub key_sequence_digest: Option<String>,
    /// Unified entities (`structure.n`, cross-checked against `extents.unified_entities`).
    pub n_entities: usize,
    /// Output rows (`extents.alignment_rows`).
    pub n_rows: usize,
    /// Segments (`extents.segments`).
    pub n_segments: usize,

    pub segment_dataset: AlignmentMemberRef,
    pub segment_start: AlignmentMemberRef,
    pub segment_end: AlignmentMemberRef,
    pub segment_order: AlignmentMemberRef,
    /// Not `Option` — the producer always writes it, and a reader that models it as
    /// absent-able cannot distinguish absence from a rename it failed to follow.
    pub entity_index: AlignmentMemberRef,
    pub entity_evidence: Option<AlignmentMemberRef>,
    pub level_lookups: Vec<AlignmentMemberRef>,

    /// From `meta.sources[]`, in the producer's order. `Segment::source_index` indexes THIS.
    pub sources: Vec<AlignmentSource>,
    /// The unified secondary identifier columns, beside `key_column`.
    pub secondary_columns: Vec<String>,
}

fn member_of(v: &Value) -> Option<AlignmentMemberRef> {
    Some(AlignmentMemberRef {
        path: v.get("path")?.as_str()?.to_string(),
        role: v.get("role")?.as_str()?.to_string(),
        dtype: v.get("dtype")?.as_str().unwrap_or_default().to_string(),
        shape: v
            .get("shape")
            .and_then(Value::as_array)
            .map(|a| {
                a.iter()
                    .filter_map(Value::as_u64)
                    .map(|n| n as usize)
                    .collect()
            })
            .unwrap_or_default(),
        extent: v
            .get("extent")
            .and_then(Value::as_array)
            .map(|a| {
                a.iter()
                    .filter_map(Value::as_str)
                    .map(str::to_string)
                    .collect()
            })
            .unwrap_or_default(),
    })
}

impl AlignmentPlan {
    /// Parse an alignment artifact's `structure` + `meta`, or say exactly what is missing.
    ///
    /// Every refusal names the ROLE or EXTENT it wanted, because the failure this replaces —
    /// reading position 3 of `aux` and getting whatever moved there — has no message at all.
    pub fn parse(structure: &Value, meta: &Value) -> Result<Self, AppError> {
        let aux: Vec<AlignmentMemberRef> = structure
            .get("aux")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                AppError::bad_request(
                    ALIGNMENT_DECLARATION_INVALID,
                    "alignment structure declares no `aux` members, so its row and segment \
                     vectors are unaddressable. An alignment without them is not an alignment",
                )
            })?
            .iter()
            .filter_map(member_of)
            .collect();

        let one = |r: &str| -> Result<AlignmentMemberRef, AppError> {
            let mut hits = aux.iter().filter(|m| m.role == r);
            let first = hits.next().cloned().ok_or_else(|| {
                AppError::bad_request(
                    ALIGNMENT_DECLARATION_INVALID,
                    format!(
                    "the alignment declares no aux member with role {r:?}. Roles present: {:?}. \
                     This side addresses members BY ROLE and never by position, so a missing \
                     role is a refusal rather than a read of whatever sits at that index",
                    aux.iter().map(|m| m.role.as_str()).collect::<Vec<_>>()
                ),
                )
            })?;
            if hits.next().is_some() {
                return Err(AppError::bad_request(
                    ALIGNMENT_DECLARATION_INVALID,
                    format!(
                    "the alignment declares MORE THAN ONE aux member with role {r:?}, which is \
                     singular by contract. Picking either would be a coin flip this side has \
                     no basis to make"
                ),
                ));
            }
            Ok(first)
        };
        let optional = |r: &str| aux.iter().find(|m| m.role == r).cloned();

        let extents = structure.get("extents").and_then(Value::as_object);
        let extent_of = |name: &str| -> Result<usize, AppError> {
            extents
                .and_then(|e| e.get(name))
                .and_then(Value::as_u64)
                .map(|n| n as usize)
                .ok_or_else(|| {
                    AppError::bad_request(
                        ALIGNMENT_DECLARATION_INVALID,
                        format!(
                            "the alignment declares no `extents.{name}`, so the length of the \
                         vectors measured in it is unknown"
                        ),
                    )
                })
        };

        let segment_dataset = one(role::SEGMENT_DATASET)?;
        let segment_start = one(role::SEGMENT_START)?;
        let segment_end = one(role::SEGMENT_END)?;
        let segment_order = one(role::SEGMENT_ORDER)?;

        let n_segments = extent_of(extent::SEGMENTS)?;
        let n_sources = extent_of(extent::SOURCES)?;
        let n_entities = extent_of(extent::UNIFIED_ENTITIES)?;

        // A member whose own shape disagrees with the extent it is measured in is a
        // producer/consumer disagreement about LENGTH, and a length disagreement is exactly
        // the shape of a read that returns the right number of the wrong rows.
        for (m, want, extent_name) in [
            (&segment_dataset, n_segments, extent::SEGMENTS),
            (&segment_start, n_segments, extent::SEGMENTS),
            (&segment_end, n_segments, extent::SEGMENTS),
            (&segment_order, n_segments, extent::SEGMENTS),
        ] {
            let got = m.len0()?;
            if got != want {
                return Err(AppError::bad_request(
                    ALIGNMENT_DECLARATION_INVALID,
                    format!(
                        "alignment member {:?} (role {:?}) declares length {got}, but its extent \
                     `{extent_name}` is {want}. The two describe the same thing and disagree",
                        m.path, m.role
                    ),
                ));
            }
        }

        let sources: Vec<AlignmentSource> = meta
            .get("sources")
            .and_then(Value::as_array)
            .ok_or_else(|| {
                AppError::bad_request(
                    ALIGNMENT_DECLARATION_INVALID,
                    "the alignment's `meta.sources` is missing. That array is where the \
                     per-source dataset ids and key-sequence digests live — without it there \
                     is nothing to check a positional read against, and INV-5 refuses an \
                     unchecked gather",
                )
            })?
            .iter()
            .map(|s| AlignmentSource {
                dataset_id: s
                    .get("dataset_id")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_string(),
                key_sequence_digest: s
                    .get("key_sequence_digest")
                    .and_then(Value::as_str)
                    .map(str::to_string),
                n_rows: s.get("n_rows").and_then(Value::as_u64).unwrap_or_default() as usize,
            })
            .collect();

        if sources.len() != n_sources {
            return Err(AppError::bad_request(
                ALIGNMENT_DECLARATION_INVALID,
                format!(
                    "the alignment declares `extents.sources` = {n_sources} but `meta.sources` \
                 carries {} entr(ies). The `segment_source` vector indexes that array, so a \
                 disagreement here addresses the wrong dataset",
                    sources.len()
                ),
            ));
        }
        if let Some(empty) = sources.iter().position(|s| s.dataset_id.is_empty()) {
            return Err(AppError::bad_request(
                ALIGNMENT_DECLARATION_INVALID,
                format!(
                "`meta.sources[{empty}]` names no `dataset_id`. A source this side cannot name \
                 is one it cannot check, name in a refusal, or keep alive through GC"
            ),
            ));
        }

        // OUTPUT row count. The ROW axis is a CONCATENATION — every source contributes ALL of
        // its rows — so `n_rows` is the SUM of the per-source `meta.sources[].n_rows`. D18
        // dropped the `extents.alignment_rows` extent (it measured only the removed row vectors);
        // the sum is the definitional value, and `bind`'s partition check proves the segment
        // table's ranges tile exactly `[0, n_rows)`, so a source count that disagreed with the
        // segments is refused rather than served short.
        let n_rows: usize = sources.iter().map(|s| s.n_rows).sum();

        let columns: Vec<&str> = structure
            .get("columns")
            .and_then(Value::as_array)
            .map(|a| {
                a.iter()
                    .filter_map(|c| c.get("name").and_then(Value::as_str))
                    .collect()
            })
            .unwrap_or_default();
        let key_column = structure
            .get("key")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                AppError::bad_request(
                    ALIGNMENT_DECLARATION_INVALID,
                    "the alignment declares no `key` column, so its unified axis has no \
                     identity to gather keys through",
                )
            })?
            .to_string();

        Ok(Self {
            axis: structure
                .get("axis")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_string(),
            secondary_columns: columns
                .iter()
                .filter(|c| **c != key_column)
                .map(|c| (*c).to_string())
                .collect(),
            key_column,
            key_sequence_digest: structure
                .get("key_sequence_digest")
                .and_then(Value::as_str)
                .map(str::to_string),
            n_entities,
            n_rows,
            n_segments,
            segment_dataset,
            segment_start,
            segment_end,
            segment_order,
            // REQUIRED, not optional — and this line is why.
            //
            // When stage 1 renamed this role, `optional()` returned `None`, `parse` SUCCEEDED,
            // and the plan read as complete with its entity index silently absent. Nothing
            // refused; the only thing that noticed was a hand-written assertion in the seam
            // test, which the previous owner had written for exactly this fear. A role lookup
            // that silently finds nothing is the class this branch keeps paying for, and
            // `optional()` cannot tell "the producer does not emit this" from "the producer
            // renamed it and I am now blind".
            //
            // The producer emits it UNCONDITIONALLY (one straight-line `table.aux(...)` in the
            // same block as the six roles already read through `one()`), and the datatype's
            // role table documents it. So it is not optional in fact, and `one()` refuses by
            // name — naming the role it wanted and listing the roles present — which is what
            // makes the NEXT rename a loud failure at the parse instead of a silent `None`.
            //
            // `entity_evidence` below stays optional deliberately: it is genuinely absent in
            // some modes, so requiring it would refuse a legitimate artifact. The distinction
            // is which member the producer always writes, not which one this reader wants.
            entity_index: one(role::ENTITY_INDEX)?,
            entity_evidence: optional(role::ENTITY_EVIDENCE),
            level_lookups: aux
                .iter()
                .filter(|m| m.role == role::LEVEL_LOOKUP)
                .cloned()
                .collect(),
            sources,
        })
    }

    /// The level-lookup member for `(column, source_index)`, if the alignment declares one.
    ///
    /// **The pair is encoded ONLY in the member's name** (`levels__<column>__<index>`) — the
    /// producer declares no `column`/`source_index` fields on the member — so this parses it,
    /// and the parser REFUSES anything that does not match rather than guessing. Parsing a
    /// composed identifier is a shape this repo otherwise avoids, and it is recorded as a
    /// stage-1 contract gap rather than accepted: the member should declare the pair.
    pub fn level_lookup_for(
        &self,
        column: &str,
        source_index: usize,
    ) -> Option<&AlignmentMemberRef> {
        let want = format!("levels__{column}__{source_index}");
        self.level_lookups
            .iter()
            .find(|m| m.path == want || m.path.rsplit('/').next() == Some(want.as_str()))
    }

    /// Every column this alignment declares a level lookup for, in first-seen order.
    ///
    /// Exists so a refusal can NAME what is on offer. `GATHER_ALIGNMENT_COLUMN_UNKNOWN`
    /// otherwise says only that the recipe's column is absent, which sends the operator to
    /// read the alignment by hand to discover it is `group` and not `values` — the exact
    /// member-path-vs-column-name confusion the refusal exists to catch.
    pub fn remapped_columns(&self) -> Vec<String> {
        let mut out: Vec<String> = Vec::new();
        for m in &self.level_lookups {
            let leaf = m.path.rsplit('/').next().unwrap_or(&m.path);
            // `levels__<column>__<source_index>` — split from the RIGHT, because a column
            // name may itself contain `__` and the source index never does.
            if let Some(rest) = leaf.strip_prefix("levels__") {
                if let Some((column, _ix)) = rest.rsplit_once("__") {
                    if !column.is_empty() && !out.iter().any(|c| c == column) {
                        out.push(column.to_string());
                    }
                }
            }
        }
        out
    }

    /// Does this alignment remap levels for `column`? If so, serving raw source codes is
    /// wrong — each source's codes are in ITS OWN code space.
    pub fn remaps_levels_for(&self, column: &str) -> bool {
        let prefix = format!("levels__{column}__");
        self.level_lookups
            .iter()
            .any(|m| m.path.starts_with(&prefix))
    }

    /// The digest pinned for one source — `None` when the producer recorded none.
    ///
    /// **Per SOURCE, deliberately.** A single pin would be right only when every source
    /// happens to share a digest, which is a coincidence, not a contract.
    pub fn digest_for(&self, source_index: usize) -> Option<&str> {
        self.sources
            .get(source_index)
            .and_then(|s| s.key_sequence_digest.as_deref())
    }

    /// The dataset ids this alignment reads through — what GC must keep reachable.
    pub fn source_dataset_ids(&self) -> Vec<&str> {
        self.sources.iter().map(|s| s.dataset_id.as_str()).collect()
    }
}

/// The alignment's VECTORS — the values, not the handles.
///
/// ## ⚠ The server cannot obtain these today, and that is a measured boundary
///
/// Every vector above is a zarr array the producer wrote with the codec chain
/// `sharding_indexed[ bytes, numcodecs.shuffle, gzip ]`. Decoding one means parsing a shard
/// index, gunzipping, and inverting a byte shuffle — i.e. opening an artifact byte for
/// meaning, which is exactly what the artifact-model's INV-1 forbids and what
/// `scripts/check-no-format-crates.sh` enforces on the dependency graph.
///
/// So this type takes the decoded vectors as an INPUT. The arithmetic over them — which
/// source a row came from, which order the segments are declared in — is pure, and is
/// testable against vectors decoded from a producer-emitted store by the test suite's own
/// reader. What is *not* available is a server-side path that produces them; that is a
/// cross-seam gap, recorded rather than implemented around.
///
/// **D18 (ITEM-11): the per-output-row `row_source` / `row_segment` vectors are GONE.** Output
/// row `i` resolves to `(source, row-within-source)` from the segment table alone
/// ([`Self::resolve_row`]), because rows are laid out in DECLARED order — the vectors merely
/// re-stated what the ranges already encode, so keeping a stored copy was a second place for
/// the two to drift apart. The `--reversed` fixture (array order ≠ declared order) is still the
/// discriminating case, and it now passes through the RANGE search, not a vector lookup.
#[derive(Debug, Clone)]
pub struct AlignmentVectors {
    /// Per segment: index into `AlignmentPlan::sources` (the source whose bytes this segment's
    /// rows come from). Equal to the segment's `declared_order`, because `meta.sources[]` is in
    /// declared order — but read from its own member, never assumed.
    pub segment_source: Vec<u32>,
    /// Per segment: the half-open output-row range this segment covers.
    pub segment_start: Vec<u64>,
    pub segment_end: Vec<u64>,
    /// Per segment: **the producer's DECLARED position, which is not the array index.**
    ///
    /// The segment arrays are serialised sorted by dataset id — deliberately, so a consumer
    /// that iterates them in array order is WRONG rather than accidentally right. Order is
    /// read from here and nowhere else.
    pub segment_order: Vec<u32>,
}

impl AlignmentVectors {
    /// Bind decoded vectors to a plan, refusing any length that disagrees with it.
    ///
    /// The plan's lengths come from the producer's declared extents; these come from the
    /// bytes. A disagreement means the two describe different runs of the producer, and a
    /// positional read across that gap returns the right count of the wrong rows.
    pub fn bind(plan: &AlignmentPlan, v: Self) -> Result<Self, AppError> {
        let check = |what: &str, got: usize, want: usize| -> Result<(), AppError> {
            if got == want {
                return Ok(());
            }
            Err(AppError::bad_request(
                ALIGNMENT_DECLARATION_INVALID,
                format!(
                    "the alignment's {what} vector decoded to {got} entr(ies) while the artifact \
                 declares {want}. The declaration and the bytes describe different runs; a \
                 positional gather across that gap returns the right NUMBER of the WRONG rows"
                ),
            ))
        };
        check("segment_source", v.segment_source.len(), plan.n_segments)?;
        check("segment_start", v.segment_start.len(), plan.n_segments)?;
        check("segment_end", v.segment_end.len(), plan.n_segments)?;
        check("segment_order", v.segment_order.len(), plan.n_segments)?;

        // CROSS-CHECK — the PARTITION property, which is what the dropped per-row vectors used
        // to cross-check (D18/INV-4). Rows are laid out in DECLARED order, so the segments'
        // `[segment_start, segment_end)` ranges must TILE `[0, n_rows)` exactly when walked in
        // declared order: no gap, no overlap, covering every row. This is independent evidence
        // rather than a restatement — it reads `segment_order` to decide the walk order, so a
        // producer that serialised the segment arrays in a non-declared order (the reversed
        // fixture) still validates, and a table that does not cover its declared row count is
        // refused rather than gathered into the right NUMBER of the WRONG rows.
        let mut walk: Vec<usize> = (0..v.segment_order.len()).collect();
        walk.sort_by_key(|&s| v.segment_order[s]);
        let mut cursor: u64 = 0;
        for &s in &walk {
            let (lo, hi) = (v.segment_start[s], v.segment_end[s]);
            if lo != cursor || hi < lo {
                return Err(AppError::bad_request(
                    ALIGNMENT_DECLARATION_INVALID,
                    format!(
                        "segment {s} (declared_order {}) covers rows {lo}..{hi}, but the segments \
                     declared before it in DECLARED order cover through row {cursor}. The \
                     declared-order layout has a gap or an overlap — a positional gather across \
                     it would return the right NUMBER of the WRONG rows",
                        v.segment_order[s]
                    ),
                ));
            }
            cursor = hi;
        }
        if cursor as usize != plan.n_rows {
            return Err(AppError::bad_request(
                ALIGNMENT_DECLARATION_INVALID,
                format!(
                    "the segment table covers {cursor} row(s) but the summed per-source row \
                     counts (`meta.sources[].n_rows`) total {}. The partition and the \
                     declaration disagree",
                    plan.n_rows
                ),
            ));
        }
        Ok(v)
    }

    /// Output row `i` → `(source index, row within that source)`, reconstructed from the
    /// segment table alone (D18/INV-4 — no stored row vector).
    ///
    /// Rows are laid out in DECLARED order, so each segment owns a DISJOINT half-open output
    /// range `[segment_start, segment_end)` and output row `i` belongs to the UNIQUE segment
    /// whose range contains it — found by RANGE, never by array position. Within that segment
    /// the row-within-source is `i - segment_start` (the declared-order layout is contiguous),
    /// and the source is `segment_source` (the segment→source map, equal to `declared_order`).
    ///
    /// This is exactly what the dropped `row_source`/`row_segment` vectors encoded — reading
    /// position `i` of `row_source` returned `i - start`, and `row_segment[i]` named the
    /// segment `i` fell in. The `--reversed` fixture (array order ≠ declared order) resolves
    /// identically here, because the range test does not depend on array order. `bind`'s
    /// partition check has already proved the ranges tile `[0, n_rows)`, so a hit is unique.
    pub fn resolve_row(&self, i: usize) -> Result<(usize, usize), AppError> {
        let seg = (0..self.segment_start.len())
            .find(|&s| (self.segment_start[s] as usize) <= i && i < (self.segment_end[s] as usize))
            .ok_or_else(|| {
                AppError::bad_request(
                    ALIGNMENT_DECLARATION_INVALID,
                    format!(
                        "output row {i} falls inside no segment's [start, end) range, so the \
                     segment table does not cover it. Reading it anyway would gather from a \
                     position the alignment never described"
                    ),
                )
            })?;
        let source = *self.segment_source.get(seg).ok_or_else(|| {
            AppError::bad_request(
                ALIGNMENT_DECLARATION_INVALID,
                format!(
                    "output row {i} names segment {seg}, but the alignment declares {}",
                    self.segment_source.len()
                ),
            )
        })? as usize;
        let row = i - self.segment_start[seg] as usize;
        Ok((source, row))
    }

    /// Segment ARRAY INDICES in the producer's declared order.
    ///
    /// This is the one place ordering is decided. Iterating the arrays in storage order, or
    /// sorting by any derived value (dataset id, first row index), permutes the picture while
    /// every count agrees — hazard H2, whose whole signature is that no length assertion sees
    /// it.
    pub fn segments_in_declared_order(&self) -> Vec<usize> {
        let mut ix: Vec<usize> = (0..self.segment_order.len()).collect();
        ix.sort_by_key(|&i| self.segment_order[i]);
        ix
    }

    /// True when array order and DECLARED order genuinely disagree.
    ///
    /// A fixture where they coincide passes against a consumer that ignores `declared_order`
    /// entirely, so a test asserting ordering must assert this FIRST. Stage 1 ran an
    /// ordering control that changed nothing for exactly this reason — the fixture's two
    /// orderings happened to be equal, so the mutation was unobservable.
    pub fn declared_order_disagrees_with_array_order(&self) -> bool {
        self.segment_order
            .iter()
            .enumerate()
            .any(|(i, &o)| o as usize != i)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    /// A structure/meta pair in the producer's shape. Small, and deliberately NOT a
    /// hand-written stand-in for the seam fixture: the seam test reads a producer-emitted
    /// artifact, and these unit tests exercise the REFUSALS, which no emitted artifact
    /// contains.
    fn structure_with(aux: Value, extents: Value) -> Value {
        json!({
            "encoding": "zarr_v3", "kind": "table", "axis": "unified_entities", "n": 2,
            "key": "unified_key", "key_sequence_digest": "sha256:unified",
            "columns": [ {"name": "unified_key"}, {"name": "unified_ensembl_id"} ],
            "arrays": [],
            "aux": aux,
            "extents": extents,
        })
    }

    fn aux_member(path: &str, role: &str, dtype: &str, n: usize, extent: &str) -> Value {
        json!({ "path": path, "name": path, "role": role, "dtype": dtype,
                "shape": [n], "extent": [extent] })
    }

    fn full_aux() -> Value {
        json!([
            aux_member(
                "segment_dataset",
                role::SEGMENT_DATASET,
                "int32",
                2,
                extent::SEGMENTS
            ),
            aux_member(
                "segment_start",
                role::SEGMENT_START,
                "int64",
                2,
                extent::SEGMENTS
            ),
            aux_member(
                "segment_end",
                role::SEGMENT_END,
                "int64",
                2,
                extent::SEGMENTS
            ),
            aux_member(
                "segment_order",
                role::SEGMENT_ORDER,
                "int32",
                2,
                extent::SEGMENTS
            ),
            // REQUIRED since `entity_index` was promoted from `optional()` to `one()` — the
            // producer writes it unconditionally, so a plan without it is not well-formed.
            //
            // These six manifests were left at the old shape when that promotion landed, and
            // every test through `full_aux()` had been RED ever since. The suite's published
            // count said `157 passed / 157, exit 0`, which was measured before the promotion
            // and not re-measured after it — the same false-green shape (a stale count read
            // as current) that hid the client parity failure for four rounds.
            aux_member(
                "entity_index",
                role::ENTITY_INDEX,
                "int32",
                2,
                extent::UNIFIED_ENTITIES
            ),
        ])
    }

    fn full_extents() -> Value {
        // D18: no `alignment_rows` — `n_rows` (5) is the sum of `meta.sources[].n_rows` (2 + 3).
        json!({ "segments": 2, "sources": 2, "unified_entities": 2 })
    }

    fn meta_2() -> Value {
        json!({ "sources": [
            {"dataset_id": "ds-a", "key_sequence_digest": "sha256:a", "n_rows": 2},
            {"dataset_id": "ds-b", "key_sequence_digest": "sha256:b", "n_rows": 3},
        ]})
    }

    #[test]
    fn parses_the_producers_member_roles_and_per_source_digests() {
        let p = AlignmentPlan::parse(&structure_with(full_aux(), full_extents()), &meta_2())
            .expect("a well-formed alignment parses");
        assert_eq!(p.segment_dataset.path, "segment_dataset");
        assert_eq!(p.n_rows, 5);
        assert_eq!(p.n_segments, 2);
        assert_eq!(p.digest_for(0), Some("sha256:a"));
        assert_eq!(p.digest_for(1), Some("sha256:b"));
        assert_eq!(p.source_dataset_ids(), vec!["ds-a", "ds-b"]);
        assert_eq!(p.secondary_columns, vec!["unified_ensembl_id".to_string()]);
    }

    /// **The role-not-position property, asserted rather than described.**
    ///
    /// Shuffling `aux` changes every member's INDEX and no member's ROLE, so a parser reading
    /// by role is unaffected and one reading by position silently addresses the wrong vector.
    #[test]
    fn members_are_addressed_by_role_not_by_array_position() {
        let forward = AlignmentPlan::parse(&structure_with(full_aux(), full_extents()), &meta_2())
            .expect("forward parses");
        let mut shuffled = full_aux().as_array().unwrap().clone();
        shuffled.reverse();
        let reversed = AlignmentPlan::parse(
            &structure_with(Value::Array(shuffled), full_extents()),
            &meta_2(),
        )
        .expect("the same members in a different array order parse identically");

        assert_eq!(forward.segment_dataset, reversed.segment_dataset);
        assert_eq!(forward.segment_start, reversed.segment_start);
        assert_eq!(forward.segment_order, reversed.segment_order);
    }

    #[test]
    fn a_missing_role_is_refused_by_name_never_read_positionally() {
        let mut aux = full_aux().as_array().unwrap().clone();
        aux.retain(|m| m["role"] != json!(role::SEGMENT_ORDER));
        let err = AlignmentPlan::parse(
            &structure_with(Value::Array(aux), full_extents()),
            &meta_2(),
        )
        .expect_err("a missing role must refuse");
        let msg = format!("{err:?}");
        assert!(
            msg.contains(role::SEGMENT_ORDER),
            "the refusal must name the role it wanted: {msg}"
        );
    }

    #[test]
    fn a_member_whose_length_contradicts_its_extent_is_refused() {
        let mut aux = full_aux().as_array().unwrap().clone();
        aux[0]["shape"] = json!([4]); // segment_dataset claims 4 while `segments` is 2
        let err = AlignmentPlan::parse(
            &structure_with(Value::Array(aux), full_extents()),
            &meta_2(),
        )
        .expect_err("a length contradiction must refuse");
        assert!(format!("{err:?}").contains("segments"));
    }

    #[test]
    fn a_source_count_that_contradicts_meta_is_refused() {
        let mut meta = meta_2();
        meta["sources"].as_array_mut().unwrap().pop();
        let err = AlignmentPlan::parse(&structure_with(full_aux(), full_extents()), &meta)
            .expect_err("segment_source would address the wrong dataset");
        assert!(format!("{err:?}").contains("segment_source"));
    }

    #[test]
    fn missing_meta_sources_is_refused_rather_than_treated_as_no_sources() {
        let err = AlignmentPlan::parse(&structure_with(full_aux(), full_extents()), &json!({}))
            .expect_err("no sources is not zero sources");
        assert!(format!("{err:?}").contains("meta.sources"));
    }

    /// An unpinned source stays `None`. **Unknown is never a match** (INV-5) — the tempting
    /// reading, "no digest recorded, nothing to check, carry on", is the silent pass the
    /// digest precheck exists to prevent.
    #[test]
    fn an_unpinned_source_reads_as_unknown_not_as_agreement() {
        let mut meta = meta_2();
        meta["sources"][1]
            .as_object_mut()
            .unwrap()
            .remove("key_sequence_digest");
        let p = AlignmentPlan::parse(&structure_with(full_aux(), full_extents()), &meta).unwrap();
        assert_eq!(p.digest_for(0), Some("sha256:a"));
        assert_eq!(p.digest_for(1), None);
    }

    fn plan() -> AlignmentPlan {
        AlignmentPlan::parse(&structure_with(full_aux(), full_extents()), &meta_2()).unwrap()
    }

    /// The forward fixture's real segment vectors, as measured from a producer run.
    fn vectors_forward() -> AlignmentVectors {
        AlignmentVectors {
            segment_source: vec![0, 1],
            segment_start: vec![0, 2],
            segment_end: vec![2, 5],
            segment_order: vec![0, 1],
        }
    }

    /// The `--reversed` fixture's real segment vectors: array order and declared order DISAGREE.
    fn vectors_reversed() -> AlignmentVectors {
        AlignmentVectors {
            segment_source: vec![1, 0],
            segment_start: vec![3, 0],
            segment_end: vec![5, 3],
            segment_order: vec![1, 0],
        }
    }

    #[test]
    fn a_row_resolves_through_its_segment_range_not_a_stored_row_vector() {
        let v = AlignmentVectors::bind(&plan(), vectors_forward()).unwrap();
        // Rows 0,1 come from source 0; rows 2,3,4 from source 1 — and rows 0 and 2 both have
        // row-within-source 0, so a stored `row_source` value alone could not tell them apart.
        // The RANGE search (D18/INV-4) does: it reads the segment the output row falls into.
        assert_eq!(v.resolve_row(0).unwrap(), (0, 0));
        assert_eq!(v.resolve_row(2).unwrap(), (1, 0));
        assert_eq!(v.resolve_row(4).unwrap(), (1, 2));
    }

    /// The `--reversed` fixture resolves IDENTICALLY through the range search, even though the
    /// segment arrays are serialised in the OPPOSITE order to the declaration — the discriminating
    /// case D18 must not regress (INV-4). Array index 0 covers output rows [3,5) from source 1;
    /// array index 1 covers [0,3) from source 0.
    #[test]
    fn the_reversed_fixture_resolves_by_range_regardless_of_array_order() {
        let v = AlignmentVectors::bind(&plan(), vectors_reversed()).unwrap();
        assert_eq!(v.resolve_row(0).unwrap(), (0, 0));
        assert_eq!(v.resolve_row(2).unwrap(), (0, 2));
        assert_eq!(v.resolve_row(3).unwrap(), (1, 0));
        assert_eq!(v.resolve_row(4).unwrap(), (1, 1));
    }

    #[test]
    fn declared_order_is_read_from_the_field_not_from_array_position() {
        let fwd = AlignmentVectors::bind(&plan(), vectors_forward()).unwrap();
        assert!(!fwd.declared_order_disagrees_with_array_order());
        assert_eq!(fwd.segments_in_declared_order(), vec![0, 1]);

        let rev = AlignmentVectors::bind(&plan(), vectors_reversed()).unwrap();
        assert!(
            rev.declared_order_disagrees_with_array_order(),
            "the reversed fixture must be a case where the two genuinely differ, or this \
             assertion passes against a consumer that ignores declared_order entirely"
        );
        assert_eq!(rev.segments_in_declared_order(), vec![1, 0]);
    }

    /// A segment vector whose LENGTH contradicts the declaration is refused (`bind`'s length
    /// check), before any range resolves.
    #[test]
    fn vectors_that_contradict_the_declaration_are_refused() {
        let mut v = vectors_forward();
        v.segment_source.pop();
        let err = AlignmentVectors::bind(&plan(), v).expect_err("a short vector must refuse");
        assert!(format!("{err:?}").contains("segment_source"));
    }

    /// A segment table that does NOT tile `[0, n_rows)` — a gap between two segments — is
    /// refused by the PARTITION check (the safety the dropped row vectors used to cross-check,
    /// D18/INV-4). nc: revert `bind` to skip the partition walk and this passes a table that
    /// would gather output rows the alignment never laid out.
    #[test]
    fn a_segment_table_with_a_gap_is_refused() {
        let mut v = vectors_forward();
        v.segment_start[1] = 3; // leaves output row 2 covered by no segment (gap at [2,3))
        v.segment_end[0] = 2;
        let err = AlignmentVectors::bind(&plan(), v).expect_err("a gap must refuse");
        let msg = format!("{err:?}");
        assert!(msg.contains("gap") || msg.contains("overlap"), "{msg}");
    }
}
